            }
          ]
        },
        "code": {
          "text": "Non-adherence and poor follow-up"
        },
        "subject": {
          "reference": "Patient/patient-1"
        }
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-1",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-1",
        "status": "final",
        "code": {
          "text": "Prior right upper quadrant ultrasound findings"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Multiple gallstones; largest 9 mm. Gallbladder wall normal. No common bile duct dilatation; common bile duct 5 mm. No pericholecystic fluid. No intrahepatic duct dilatation."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-2",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-2",
        "status": "final",
        "code": {
          "text": "History of upper abdominal pain"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Intermittent right upper quadrant/epigastric colicky pain for 6 months, sometimes radiating to the right shoulder; up to 7/10, usually lasting 30–60 minutes, with two episodes lasting 2–3 hours. Mostly in the evenings and after fatty meals; approximately 3–4 episodes per month. One nocturnal episode last week settled with ibuprofen."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-3",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-3",
        "status": "final",
        "code": {
          "text": "Symptoms accompanying severe pain episodes"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Nausea with severe episodes. Denies vomiting, fever, rigors, jaundice, dark urine, pale stool, rectal bleeding, and melaena."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-4",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-4",
        "status": "final",
        "code": {
          "text": "Current symptoms"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Asymptomatic today; specifically denies current pain, fever, rigors, shortness of breath, chest pain, and vomiting."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-5",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-5",
        "status": "final",
        "code": {
          "text": "Constitutional symptoms"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "No weight loss or night sweats."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-6",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-6",
        "status": "final",
        "code": {
          "text": "Blood pressure"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
